@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <aside class="settings-nav">
        <h5 class="mb-3 px-2">Settings</h5>
        <SettingsSidebar ActiveSection="@_activeSection"
                         OnSectionSelected="section => _activeSection = section" />
    </aside>

    <section class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </section>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-nav {
    min-width: 220px;
    max-width: 220px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

